func (this *Hyperliquid) InitializeClientAsync() <-chan AsyncResult[bool] {
	ch := make(chan AsyncResult[bool], 1)
	go this.initializeClientBody(ch)
	return ch
}
func (this *Hyperliquid) initializeClientBody(ch chan AsyncResult[bool]) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	chSent := false
	_ = chSent

	{
		func(this *Hyperliquid) (ret_ any) {
			defer func() {
				if e := recover(); e != nil {
					if e == "break" {
						return
					}
					ret_ = func(this *Hyperliquid) any {
						// catch block:

						ch <- AsyncResult[bool]{Value: false}
						chSent = true
						return nil

					}(this)
				}
			}()
			// try block:
			// each call settles before the next: they write this.options, which a parallel Promise.all would race on in Go
			var refSet *bool = this.SafeBool(this.Options, "refSet", false)
			this.Options["refSet"] = true

			r := <-this.HandleBuilderFeeApprovalAsync()
			if r.Err != nil {
				panic(r.Err)
			}
			var feeApproved bool = r.Value
			if feeApproved == true {
				this.Options["approvedBuilderFee"] = true
			} else {
				this.Options["builderFee"] = false // disable builder fee if an error occurs
			}

			r1 := <-this.SetRefAsync(refSet)
			if r1.Err != nil {
				panic(r1.Err)
			}

			r2 := <-promiseAll([]any{this.IsUnifiedEnabledAsync("fetchBalance", nil, false, map[string]any{})}) // for now only fetchBalance requires the unified knowledge, but we can extend this to other methods as needed
			if r2.Err != nil {
				panic(r2.Err)
			}
			return nil
		}(this)
		if chSent {
			return nil
		}

	}

	ch <- AsyncResult[bool]{Value: true}
	return nil
}
func (this *Hyperliquid) HandleBuilderFeeApprovalAsync() <-chan AsyncResult[bool] {
	ch := make(chan AsyncResult[bool], 1)
	go this.handleBuilderFeeApprovalBody(ch)
	return ch
}
func (this *Hyperliquid) handleBuilderFeeApprovalBody(ch chan AsyncResult[bool]) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	chSent := false
	_ = chSent
	var buildFee *bool = this.SafeBool(this.Options, "builderFee", true)
	var approvedBuilderFee *bool = this.SafeBool(this.Options, "approvedBuilderFee", false)
	if approvedBuilderFee != nil && *approvedBuilderFee {

		ch <- AsyncResult[bool]{Value: true} // skip if builder fee is already approved
		return nil
	}

	{
		func(this *Hyperliquid) (ret_ any) {
			defer func() {
				if e := recover(); e != nil {
					if e == "break" {
						return
					}
					ret_ = func(this *Hyperliquid) any {
						// catch block:

						ch <- AsyncResult[bool]{Value: false}
						chSent = true
						return nil

					}(this)
				}
			}()
			// try block:
			var builder string = *this.SafeString(this.Options, "builder", "0x6530512A6c89C7cfCEbC3BA7fcD9aDa5f30827a6")
			// when the user disables the builder fee (builderFee = false) we still approve and attach the builder,
			// but with a 0% fee rate, so orders remain attributed to the builder for statistics purposes only and the user is not charged
			var maxFeeRate string = *this.SafeString(this.Options, "feeRate", "0.01%")
			if !(buildFee != nil && *buildFee) {
				maxFeeRate = "0%"
			}

			r := <-this.ApproveBuilderFeeAsync(builder, maxFeeRate)
			if r.Err != nil {
				panic(r.Err)
			}
			return nil
		}(this)
		if chSent {
			return nil
		}

	}

	ch <- AsyncResult[bool]{Value: true}
	return nil
}

/**
 * @method
 * @name hyperliquid#isUnifiedEnabled
 * @see https://hyperliquid.gitbook.io/hyperliquid-docs/for-developers/api/info-endpoint#query-a-users-abstraction-state
 * @description returns enableUnifiedMargin so the user can check if unified account is enabled
 * @param {string} method the method for which we want to check if unified margin is enabled, this is used to check options for specific methods (e.g. fetchBalance can have a specific option to enable unified margin)
 * @param {string} [address] the wallet address to query; defaults to the configured walletAddress
 * @param {boolean} [shouldRefresh] force a fresh request instead of returning the cached value
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {bool} enableUnifiedMargin
 */
func (this *Hyperliquid) IsUnifiedEnabledAsync(method string, optionalArgs ...any) <-chan AsyncResult[MapPair[any]] {
	ch := make(chan AsyncResult[MapPair[any]], 1)
	go this.isUnifiedEnabledBody(ch, method, optionalArgs...)
	return ch
}
func (this *Hyperliquid) isUnifiedEnabledBody(ch chan AsyncResult[MapPair[any]], method string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var address *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = address
	var shouldRefresh bool = GetArgBool(optionalArgs, 1, false)
	_ = shouldRefresh
	var params map[string]any = GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params
	var publicAddress any = nil
	var paramsPublicAddress map[string]any = map[string]any{}
	if address == nil {
		publicAddressparamsPublicAddressVariable := this.HandlePublicAddress("isUnifiedEnabled", params)
		publicAddress = GetValue(publicAddressparamsPublicAddressVariable, 0)
		paramsPublicAddress = MapTyped(publicAddressparamsPublicAddressVariable[1])
	}
	var userAddress any
	if address != nil {
		userAddress = address
	} else {
		userAddress = publicAddress
	}
	var paramsAddress map[string]any
	if address != nil {
		paramsAddress = params
	} else {
		paramsAddress = paramsPublicAddress
	}
	var enableUnifiedMarginOptionPtr *bool = nil
	enableUnifiedMarginOptionPtr, paramsEnableUnifiedMargin := this.HandleOptionBoolAndParamsNullable(paramsAddress, method, "enableUnifiedMargin")
	enableUnifiedMarginOption := func() any {
		if enableUnifiedMarginOptionPtr != nil {
			return *enableUnifiedMarginOptionPtr
		}
		return nil
	}()
	var enableUnifiedMargin any = enableUnifiedMarginOption
	if IsEqual(enableUnifiedMargin, nil) || (shouldRefresh == true) {
		var request map[string]any = map[string]any{
			"type": "userAbstraction",
			"user": userAddress,
		}
		var response *string = nil

		{
			func(this *Hyperliquid) (ret_ any) {
				defer func() {
					if e := recover(); e != nil {
						if e == "break" {
							return
						}
						ret_ = func(this *Hyperliquid) any {
							// catch block:
							if IsInstance(e, InvalidProxySettings) {
								panic(e)
							}
							response = nil // ignore this error and assume unified margin is not enabled
							return nil
						}(this)
					}
				}()
				// try block:
				// the request keys win: a caller's own 'type' or 'user' params (e.g. transfer's
				// type 'swap') must not overwrite the info query, which would silently fail here

				r := <-this.PublicPostInfo(this.Extend(paramsEnableUnifiedMargin, request))
				if r.Err != nil {
					panic(r.Err)
				}
				rawResponse := r.Value
				if rawResponseStr, ok := rawResponse.(string); ok {
					response = &rawResponseStr
				}
				return nil
			}(this)

		}
		//
		// "unifiedAccount" | "portfolioMargin" | "disabled" | "default" | "dexAbstraction"
		//
		if response != nil {
			enableUnifiedMargin = (strings.ReplaceAll(*response, "\"", "") == "unifiedAccount")
		}
		// don't cache this result if this is a different addresss
		this.Options["enableUnifiedMargin"] = enableUnifiedMargin // cache this for future calls
	}

	ch <- AsyncResult[MapPair[any]]{Value: MapPair[any]{V: enableUnifiedMargin, P: MapTyped(paramsEnableUnifiedMargin)}}
	return nil
}

