func (this *Hyperliquid) EditOrdersRequest(orders []map[string]any, optionalArgs ...any) map[string]any {
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	this.CheckRequiredCredentials()
	var hasClientOrderId bool = false
	var ordersLength int = len(orders)
	for i := 0; i < ordersLength; i++ {
		var rawOrder map[string]any = orders[i]
		var orderParams, _ = rawOrder["params"].(map[string]any)
		var clientOrderId *string = this.SafeString2(orderParams, "clientOrderId", "client_id")
		if clientOrderId != nil {
			hasClientOrderId = true
		}
	}
	if hasClientOrderId {
		for i := 0; i < ordersLength; i++ {
			var rawOrder map[string]any = orders[i]
			var orderParams, _ = rawOrder["params"].(map[string]any)
			var clientOrderId *string = this.SafeString2(orderParams, "clientOrderId", "client_id")
			if clientOrderId == nil {
				panic(ArgumentsRequired(this.Id + " editOrders() all orders must have clientOrderId if at least one has a clientOrderId"))
			}
		}
	}
	var params2 map[string]any = this.OmitDict(params, []any{"slippage", "clientOrderId", "client_id", "slippage", "triggerPrice", "stopPrice", "stopLossPrice", "takeProfitPrice", "timeInForce"})
	var modifies []any = []any{}
	for i := 0; i < ordersLength; i++ {
		var rawOrder map[string]any = orders[i]
		var id *string = this.SafeString(rawOrder, "id")
		var marketId *string = this.SafeString(rawOrder, "symbol")
		var market map[string]any = this.Market(marketId)
		var symbol string = *this.SafeString(market, "symbol", "")
		var typeVar *string = this.SafeStringUpper(rawOrder, "type")
		var isMarket bool = (typeVar != nil && *typeVar == "MARKET")
		var side *string = this.SafeStringUpper(rawOrder, "side")
		var isBuy bool = (side != nil && *side == "BUY")
		var amount *string = this.SafeString(rawOrder, "amount")
		var price *string = this.SafeString(rawOrder, "price")
		var orderParams map[string]any
		orderParams, _ = rawOrder["params"].(map[string]any)
		if orderParams == nil {
			orderParams = map[string]any{}
		}
		var defaultSlippage *string = this.SafeString(this.Options, "defaultSlippage")
		var slippage *string = this.SafeString(orderParams, "slippage", defaultSlippage)
		var defaultTimeInForce string = "gtc"
		if isMarket {
			defaultTimeInForce = "ioc"
		}
		var postOnly *bool = this.SafeBool(orderParams, "postOnly", false)
		if postOnly != nil && *postOnly {
			defaultTimeInForce = "alo"
		}
		var timeInForceLower *string = this.SafeStringLower(orderParams, "timeInForce", defaultTimeInForce)
		if timeInForceLower != nil && *timeInForceLower == "po" {
			timeInForceLowerStr := "alo"
			timeInForceLower = &timeInForceLowerStr // the unified post-only time in force is called Alo on hyperliquid
		}
		var timeInForce string = this.Capitalize(timeInForceLower)
		var clientOrderId *string = this.SafeString2(orderParams, "clientOrderId", "client_id")
		var triggerPrice *string = this.SafeString2(orderParams, "triggerPrice", "stopPrice")
		var stopLossPrice *string = this.SafeString(orderParams, "stopLossPrice", triggerPrice)
		var takeProfitPrice *string = this.SafeString(orderParams, "takeProfitPrice")
		var isTrigger bool = ((stopLossPrice != nil) || (takeProfitPrice != nil))
		var reduceOnly *bool = this.SafeBool(orderParams, "reduceOnly", false)
		orderParams = this.OmitDict(orderParams, []any{"slippage", "timeInForce", "triggerPrice", "stopLossPrice", "takeProfitPrice", "clientOrderId", "client_id", "postOnly", "reduceOnly"})
		var px any
		if derefPtr := this.NumberToString(price); derefPtr != nil {
			px = *derefPtr
		}
		if isMarket {
			if isBuy {
				px = Precise.StringMul(px, Precise.StringAdd("1", slippage))
			} else {
				px = Precise.StringMul(px, Precise.StringSub("1", slippage))
			}
			if derefPtr := this.PriceToPrecision(symbol, px); derefPtr != nil {
				px = *derefPtr
			} else {
				px = nil
			}
		} else {
			if derefPtr := this.PriceToPrecision(symbol, px); derefPtr != nil {
				px = *derefPtr
			} else {
				px = nil
			}
		}
		var sz *string = this.AmountToPrecision(symbol, amount)
		var orderType map[string]any = map[string]any{}
		if isTrigger {
			var isTp bool = false
			if takeProfitPrice != nil {
				triggerPrice = this.PriceToPrecision(symbol, takeProfitPrice)
				isTp = true
			} else {
				triggerPrice = this.PriceToPrecision(symbol, stopLossPrice)
			}
			var tpSlType string = "sl"
			if isTp {
				tpSlType = "tp"
			}
			orderType["trigger"] = map[string]any{
				"isMarket":  isMarket,
				"triggerPx": triggerPrice,
				"tpsl":      tpSlType,
			}
		} else {
			orderType["limit"] = map[string]any{
				"tif": timeInForce,
			}
		}
		if triggerPrice == nil {
			triggerPriceStr := "0"
			triggerPrice = &triggerPriceStr
		}
		var orderReq map[string]any = map[string]any{
			"a": this.ParseToInt(market["baseId"]),
			"b": isBuy,
			"p": px,
			"s": sz,
			"r": reduceOnly,
			"t": orderType,
		}
		if clientOrderId != nil {
			orderReq["c"] = clientOrderId
		}
		var modifyReq map[string]any = map[string]any{
			"oid":   this.ParseToInt(id),
			"order": orderReq,
		}
		modifies = append(modifies, modifyReq)
	}
	var nonce int64 = this.IncrementingNonce()
	var modifyAction map[string]any = map[string]any{
		"type":     "batchModify",
		"modifies": modifies,
	}
	vaultAddressOption, _ := this.HandleOptionStringAndParams(params2, "editOrder", "vaultAddress")
	var vaultAddress *string = this.FormatVaultAddress(vaultAddressOption)
	var signature map[string]any = this.SignL1Action(modifyAction, nonce, vaultAddress)
	var request map[string]any = map[string]any{
		"action":    modifyAction,
		"nonce":     nonce,
		"signature": signature,
	}
	if vaultAddress != nil {
		request["vaultAddress"] = vaultAddress
	}
	return request
}

/**
 * @method
 * @name hyperliquid#editOrder
 * @description edit a trade order
 * @see https://hyperliquid.gitbook.io/hyperliquid-docs/for-developers/api/exchange-endpoint#modify-multiple-orders
 * @param {string} id cancel order id
 * @param {string} symbol unified symbol of the market to create an order in
 * @param {string} type 'market' or 'limit'
 * @param {string} side 'buy' or 'sell'
 * @param {float} amount how much of currency you want to trade in units of base currency
 * @param {float} [price] the price at which the order is to be fulfilled, in units of the quote currency, ignored in market orders
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.timeInForce] 'Gtc', 'Ioc', 'Alo'
 * @param {bool} [params.postOnly] true or false whether the order is post-only
 * @param {bool} [params.reduceOnly] true or false whether the order is reduce-only
 * @param {float} [params.triggerPrice] The price at which a trigger order is triggered at
 * @param {string} [params.clientOrderId] client order id, (optional 128 bit hex string e.g. 0x1234567890abcdef1234567890abcdef)
 * @param {string} [params.vaultAddress] the vault address for order
 * @param {string} [params.subAccountAddress] sub account user address
 * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Hyperliquid) EditOrderAsync(id string, symbol string, typeVar string, side string, optionalArgs ...any) <-chan AsyncResult[Order] {
	ch := make(chan AsyncResult[Order], 1)
	go this.editOrderBody(ch, id, symbol, typeVar, side, optionalArgs...)
	return ch
}
func (this *Hyperliquid) editOrderBody(ch chan AsyncResult[Order], id string, symbol string, typeVar string, side string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	amount := GetArg(optionalArgs, 0, nil)
	_ = amount
	var price *float64 = GetArgFloat64Ptr(optionalArgs, 1, nil)
	_ = price
	var params map[string]any = GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params
	if this.Markets == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	if false {
		panic(ArgumentsRequired(this.Id + " editOrder() requires an id argument"))
	}
	order, globalParams := this.ParseCreateEditOrderArgs(&id, &symbol, &typeVar, &side, amount, price, params)

	r1 := <-this.EditOrdersAsync([]map[string]any{order}, globalParams)
	if r1.Err != nil {
		panic(r1.Err)
	}
	var orders []Order = r1.Value
	var edited Order
	if len(orders) > 0 {
		edited = orders[0]
	}

	ch <- AsyncResult[Order]{Value: edited}
	return nil
}

