	r1 := <-this.InitializeClientAsync()
	if r1.Err != nil {
		panic(r1.Err)
	}
	var request map[string]any = this.EditOrdersRequest(orders, params)

	r2 := <-this.PrivatePostExchange(request)
	if r2.Err != nil {
		panic(r2.Err)
	}
	var response map[string]any = r2.Value
	//
	//     {
	//         "status": "ok",
	//         "response": {
	//             "type": "order",
	//             "data": {
	//                 "statuses": [
	//                     {
	//                         "resting": {
	//                             "oid": 5063830287
	//                         }
	//                     }
	//                 ]
	//             }
	//         }
	//     }
	// when the order is filled immediately
	//     {
	//         "status":"ok",
	//         "response":{
	//            "type":"order",
	//            "data":{
