func (this *Hyperliquid) ParseLedgerEntry(item map[string]any, optionalArgs ...any) LedgerEntry {
	//
	// {
	//     "time":1724762307531,
	//     "hash":"0x620a234a7e0eb7930575040f59482a01050058b0802163b4767bfd9033e77781",
	//     "delta":{
	//         "type":"accountClassTransfer",
	//         "usdc":"50.0",
	//         "toPerp":false
	//     }
	// }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var timestamp *int64 = this.SafeInteger(item, "time")
	var delta, _ = item["delta"].(map[string]any)
	var fee map[string]any = nil
	var feeCost *int64 = this.SafeInteger(delta, "fee")
	if feeCost != nil {
		fee = map[string]any{
			"currency": "USDC",
			"cost":     feeCost,
		}
	}
	var typeVar *string = this.SafeString(delta, "type")
	var amount *string = this.SafeString(delta, "usdc")
	return this.SafeLedgerEntry(map[string]any{
		"info":             item,
		"id":               this.SafeString(item, "hash"),
		"direction":        nil,
		"account":          nil,
		"referenceAccount": this.SafeString(delta, "user"),
		"referenceId":      this.SafeString(item, "hash"),
		"type":             this.ParseLedgerEntryType(typeVar),
		"currency":         nil,
		"amount":           this.ParseNumber(amount),
		"timestamp":        timestamp,
		"datetime":         this.Iso8601(timestamp),
		"before":           nil,
		"after":            nil,
		"status":           nil,
		"fee":              fee,
	}, currency)
}
func (this *Hyperliquid) ParseLedgerEntryType(typeVar *string) *string {
	var ledgerType map[string]any = map[string]any{
		"internalTransfer":     "transfer",
		"accountClassTransfer": "transfer",
	}
	return this.SafeString(ledgerType, typeVar, typeVar)
}

/**
 * @method
 * @name hyperliquid#fetchDeposits
 * @description fetch all deposits made to an account
 * @param {string} code unified currency code
 * @param {int} [since] the earliest time in ms to fetch deposits for
 * @param {int} [limit] the maximum number of deposits structures to retrieve
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {int} [params.until] the latest time in ms to fetch withdrawals for
 * @param {string} [params.subAccountAddress] sub account user address
 * @param {string} [params.vaultAddress] vault address
 * @returns {object[]} a list of [transaction structures]{@link https://docs.ccxt.com/?id=transaction-structure}
 */
func (this *Hyperliquid) FetchDepositsAsync(optionalArgs ...any) <-chan AsyncResult[[]Transaction] {
	ch := make(chan AsyncResult[[]Transaction], 1)
	go this.fetchDepositsBody(ch, optionalArgs...)
	return ch
}
func (this *Hyperliquid) fetchDepositsBody(ch chan AsyncResult[[]Transaction], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var code *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = code
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var userAddress *string = nil
	var params2 map[string]any = nil
	userAddressparams2Variable := this.HandlePublicAddress("fetchDepositsWithdrawals", params)
	userAddress = SafeStringPtr(userAddressparams2Variable[0])
	params2 = MapTyped(userAddressparams2Variable[1])
	var request map[string]any = map[string]any{
		"type": "userNonFundingLedgerUpdates",
		"user": userAddress,
	}
	if since != nil {
		request["startTime"] = *since
	}
	var until *int64 = this.SafeInteger(params2, "until")
	if until != nil {
		if since == nil {
			panic(ArgumentsRequired(this.Id + " fetchDeposits requires since while until is set"))
		}
		request["endTime"] = until
		params2 = this.OmitDict(params2, []any{"until"})
	}

	r1 := <-this.PublicPostInfo(this.Extend(request, params2))
	if r1.Err != nil {
		panic(r1.Err)
	}
	depositLedgerResponse := r1.Value
	var depositLedger []any = this.InfoList(depositLedgerResponse)
	//
	// [
	//     {
	//         "time":1724762307531,
	//         "hash":"0x620a234a7e0eb7930575040f59482a01050058b0802163b4767bfd9033e77781",
	//         "delta":{
	//             "type":"accountClassTransfer",
	//             "usdc":"50.0",
	//             "toPerp":false
	//         }
	//     }
	// ]
	//
	var records []any = this.ExtractTypeFromDelta(depositLedger)
	vaultAddressOption, _ := this.HandleOptionStringAndParams(params2, "fetchDepositsWithdrawals", "vaultAddress")
	var vaultAddress *string = this.FormatVaultAddress(vaultAddressOption)
	if vaultAddress == nil {
		var filtered any = this.FilterByArray(records, "type", []any{"deposit"}, false)

		ch <- AsyncResult[[]Transaction]{Value: TransactionsFromList(this.ParseTransactions(filtered, nil, since, limit))}
		return nil
	}
	var deposits []any = []any{}
	for i := 0; i < len(records); i++ {
		var record any = records[i]
		if this.SafeString(record, "type") != nil && *this.SafeString(record, "type") == "vaultDeposit" {
			var delta map[string]any = SafeMapTyped(record, "delta")
			var deltaVault string = *this.SafeString(delta, "vault", "")
			if deltaVault == "0x"+*vaultAddress {
				deposits = append(deposits, record)
			}
		}
	}

	ch <- AsyncResult[[]Transaction]{Value: TransactionsFromList(this.ParseTransactions(deposits, nil, since, limit))}
	return nil
}

